public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    final boolean[] used = new boolean[nums.length];
    final List<Integer> temp = new ArrayList<>();
    class Solver {
        void dfs() {
            if (temp.size() == nums.length) {
                res.add(new ArrayList<>(temp));
                return;
            }
            for (int i = 0; i < nums.length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    temp.add(nums[i]);
                    dfs();
                    temp.remove(temp.size() - 1);
                    used[i] = false;
                }
            }
        }
    }
    new Solver().dfs();
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Filter out null strings and ensure at least one non-empty string
    List<String> nonNull = new java.util.ArrayList<>();
    for (String s : strings) {
        if (s != null) {
            nonNull.add(s);
        }
    }
    if (nonNull.isEmpty()) {
        return 0;
    }

    // Find the shortest string to limit substring candidates
    String minS = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : nonNull) {
        if (s.length() < minLen) {
            minLen = s.length();
            minS = s;
        }
    }
    if (minS == null || minLen == 0) {
        return 0;
    }

    // Iterate possible lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        // Use a set to avoid duplicate substrings for this length
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int start = 0; start <= minS.length() - len; start++) {
            String sub = minS.substring(start, start + len);
            if (!seen.add(sub)) continue; // skip duplicates

            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : nonNull) {
                if (!s.contains(sub) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len; // longest found
            }
        }
    }
    return 0; // No substring found
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) continue;
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // Iterative DFS using stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    int cr = cur[0], cc = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

