public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null) {
            return "cannot be travelled";
        }
        if (start.length != n || end.length != n) {
            return "cannot be travelled";
        }
        // Convert coordinates to string key
        java.util.function.Function<int[], String> keyFromCoords = coords -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coords.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(coords[i]);
            }
            return sb.toString();
        };
        String startKey = keyFromCoords.apply(start);
        String endKey = keyFromCoords.apply(end);
        if (startKey.equals(endKey)) {
            return "can be travelled";
        }

        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

        if (paths != null) {
            for (int[] path : paths) {
                if (path == null || path.length != 2 * n) {
                    continue; // ignore malformed row
                }
                int[] p1 = new int[n];
                int[] p2 = new int[n];
                System.arraycopy(path, 0, p1, 0, n);
                System.arraycopy(path, n, p2, 0, n);
                String p1Key = keyFromCoords.apply(p1);
                String p2Key = keyFromCoords.apply(p2);
                graph.computeIfAbsent(p1Key, k -> new java.util.ArrayList<>()).add(p2Key);
                graph.computeIfAbsent(p2Key, k -> new java.util.ArrayList<>()).add(p1Key);
            }
        }

        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
            for (String nb : neighbors) {
                if (visited.contains(nb)) continue;
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.add(nb);
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

