    }
    int count = end - start + 1;
    return sum / (double) count;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be positive");
    }
    if (arr.length % 2 != 0) {
        return false; // cannot pair all elements
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k; // ensure non‑negative remainder
        }
        freq[r] += 1;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also have even frequency
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled when k is even
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null) return 0;
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length < 2) continue;
            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            adj[u].add(v);
            adj[v].add(u);
        }
    }
    boolean[] visited = new boolean[n];
    int[] total = new int[1];
    dfs(0, adj, visited, hasApple, total);
    return total[0];
}

private boolean dfs(int node, List<Integer>[] adj, boolean[] visited, boolean[] hasApple, int[] total) {
    visited[node] = true;
    boolean has = hasApple[node];
    for (int nb : adj[node]) {
        if (!visited[nb]) {
            boolean childHas = dfs(nb, adj, visited, hasApple, total);
            if (childHas) total[0] += 2;
            has = has || childHas;
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[65536];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    int remaining = s.length();
    StringBuilder sb = new StringBuilder(remaining);
    while (remaining > 0) {
        // Ascending pass
        int minIdx = -1;
        for (int i = 0; i < 65536 && minIdx == -1; i++) {
            if (freq[i] > 0) {
                minIdx = i;
            }
        }
        if (minIdx == -1) {
            break;
        }
        sb.append((char) minIdx);
        freq[minIdx]--;
        remaining--;
        int last = minIdx;
        while (remaining > 0) {
            int next = -1;
            for (int i = last + 1; i < 65536; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            sb.append((char) next);
            freq[next]--;
            remaining--;
            last = next;
        }
        if (remaining == 0) {
            break;
        }
        // Descending pass
        int maxIdx = -1;
        for (int i = 65535; i >= 0 && maxIdx == -1; i--) {
            if (freq[i] > 0) {
                maxIdx = i;
            }
        }
        if (maxIdx == -1) {
            break;
        }
        sb.append((char) maxIdx);
        freq[maxIdx]--;
        remaining--;
        last = maxIdx;
        while (remaining > 0) {
            int prev = -1;
            for (int i = last - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    prev = i;
                    break;
                }
            }
            if (prev == -1) {
                break;
            }
            sb.append((char) prev);
            freq[prev]--;
            remaining--;
            last = prev;
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int v : nums) total += v;
    int half = n / 2;
    // sets[k] holds all possible sums of subsets with size k
    java.util.List<java.util.Set<Integer>> sets = new java.util.ArrayList<>(half + 1);
    for (int i = 0; i <= half; i++) {
        sets.add(new java.util.HashSet<>());
    }
    sets.get(0).add(0);
    for (int idx = 0; idx < n; idx++) {
        int val = nums[idx];
        // iterate k backwards to avoid reuse of current val in same iteration
        int maxK = Math.min(half, idx + 1);
        for (int k = maxK; k >= 1; k--) {
            java.util.Set<Integer> prev = sets.get(k - 1);
            java.util.Set<Integer> curr = sets.get(k);
            for (int s : prev) {
                curr.add(s + val);
            }
        }
    }
    for (int k = 1; k <= half; k++) {
        long lhs = (long) total * k;
        if (lhs % n != 0) continue;
        int target = (int) (lhs / n);
        if (sets.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    int[] dp = new int[n + 1];
    // dp[0] and dp[1] are initialized to 0 by default,
    // representing the option to start at step 0 or step 1 without paying cost.
    for (int i = 2; i <= n; i++) {
        int fromOne = dp[i - 1] + cost[i - 1];
        int fromTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromOne, fromTwo);
    }
    return dp[n];
}

public int uniqueMorseRepresentations(String[] words) {
    // Mapping of letters a-z to Morse code
    final String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..",  // a-i
        ".---", "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", // j-r
        "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."          // s-z
    };

    if (words == null || words.length == 0) {
        return 0;
    }

    java.util.Set<String> uniqueSet = new java.util.HashSet<>();

    for (String word : words) {
        if (word == null || word.isEmpty()) {
            continue; // Skip null or empty strings
        }
        StringBuilder sb = new StringBuilder();
        boolean valid = true;
        for (char ch : word.toCharArray()) {
            if (ch >= 'a' && ch <= 'z') {
                sb.append(morse[ch - 'a']);
            } else if (ch >= 'A' && ch <= 'Z') {
                sb.append(morse[ch - 'A']);
            } else {
                // Unsupported character; skip this word
                valid = false;
                break;
            }
        }
        if (valid) {
            uniqueSet.add(sb.toString());
        }
    }

    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k < 0) {
        throw new IllegalArgumentException("k must be non-negative");
    }
    // Special case: k == 0 -> every binary string of length 0 (the empty string) is trivially present
    if (k == 0) {
        return true;
    }

    int n = s.length();
    // If k is too large, 2^k exceeds reasonable bounds for storage and string length.
    // For practicality, we limit k to 20 (2^20 = 1,048,576), which is sufficient for usual constraints.
    if (k > 20) {
        // Early check: even the minimal possible length to contain all codes is 2^k + k - 1.
        // If s is shorter than that, it cannot contain all codes.
        // We use long to avoid overflow.
        long minLen = ((1L << k) + k - 1);
        if (n < minLen) {
            return false;
        }
        // For k > 20 and s length sufficient, storing all patterns is infeasible.
        // Decline to compute and return false to avoid excessive memory usage.
        return false;
    }

    int totalCodes = 1 << k;                 // total distinct binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = totalCodes - 1;               // to keep only the last k bits

    int current = 0;
    for (int i = 0; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {                    // a complete window of length k is achieved
            if (!seen[current]) {
                seen[current] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true;             // all codes seen early
                }
            }
        }
    }
    return seenCount == totalCodes;
}

public int isPrefixOfWord(String sentence, String searchWord) {
