}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int leftNeeded = 0;   // number of '(' needed to balance encountered ')'
    int rightNeeded = 0;  // number of ')' needed to close open '('

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            rightNeeded++;          // one more ')' needed to close this '('
        } else if (c == ')') {
            if (rightNeeded > 0) {
                rightNeeded--;     // this ')' matches a previous '('
            } else {
                leftNeeded++;       // this ')' needs an inserted '(' before it
            }
        }
    }

    return leftNeeded + rightNeeded;
}

