public int maxAbsoluteSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = nums.length;
    if (n == 0) {
        return 0;
    }

    int maxSum = Integer.MIN_VALUE;
    int currentMax = 0;
    int minSum = Integer.MAX_VALUE;
    int currentMin = 0;

    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);

        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    // Generate Fibonacci numbers up to k (unique sequence: 1, 2, 3, 5, 8, ...)
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(2);
    while (true) {
        int sz = fibs.size();
        long next = (long) fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) {
            break;
        }
        fibs.add((int) next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int complement = n / i;
            if (complement != i) {
                factors.add(complement);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    // Handle null input: return null to signify invalid input
    if (s == null) {
        return null;
    }

    int n = s.length();
    char[] stack = new char[n];
    int top = 0;

    for (int i = 0; i < n; i++) {
        char current = s.charAt(i);

        if (top > 0) {
            char prev = stack[top - 1];
            // Check if current and prev are the same letter with opposite cases
            if (Character.toLowerCase(current) == Character.toLowerCase(prev)
                && current != prev) {
                // Remove the pair by popping the stack
                top--;
                continue;
            }
        }
        // Push current character onto the stack
        stack[top++] = current;
    }

    return new String(stack, 0, top);
}

public int maxUniqueSplit(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    if (n < 1 || n > 16) {
        throw new IllegalArgumentException("String length must be between 1 and 16");
    }
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("String must contain only lowercase English letters");
        }
    }
    return dfs(0, s, new HashSet<>());
}

private int dfs(int pos, String s, Set<String> used) {
    if (pos == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int count = 1 + dfs(end, s, used);
            if (count > max) {
                max = count;
            }
            used.remove(sub);
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    int depth = 0;
    if (logs == null) {
        return 0;
    }
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        try {
            if ("../".equals(log)) {
                if (depth > 0) {
                    depth--;
                }
            } else if ("./".equals(log)) {
                // no operation needed
            } else {
                // Treat any other non-empty string as a folder name
                depth++;
            }
        } catch (Exception e) {
            // In case of unexpected runtime issues, skip the log entry
            continue;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate inputs
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) { // use long to avoid overflow if k is large
        throw new IllegalArgumentException("Invalid value for k: must satisfy n <= k <= 26*n");
    }

    char[] result = new char[n];
    // Initialize with 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // how much we need to add beyond the initial 'a's

    // Distribute the remaining sum starting from the end to keep string lexicographically minimal
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int maxAdd = 26 - 1; // maximum increase from 'a' to 'z'
        int add = Math.min(maxAdd, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

