public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }
    int result = 0;
    // Iterate over each bit position
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            // Extract the ith bit (0-indexed from LSB)
            bitCount += (num >> i) & 1;
        }
        // Modulo 3 to isolate the single number's bit
        int bit = bitCount % 3;
        result |= (bit << i);
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result;
    }
    // Handle 0 separately if within range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    // For digits 1 through 9, generate stepping numbers via BFS
    for (int start = 1; start <= 9; start++) {
        Queue<Long> queue = new ArrayDeque<>();
        queue.offer((long) start);
        while (!queue.isEmpty()) {
            long cur = queue.poll();
            if (cur > high) {
                continue;
            }
            if (cur >= low) {
                result.add((int) cur);
            }
            long lastDigit = cur % 10;
            // Append lastDigit - 1
            if (lastDigit > 0) {
                long next = cur * 10 + (lastDigit - 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
            // Append lastDigit + 1
            if (lastDigit < 9) {
                long next = cur * 10 + (lastDigit + 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        if (factor > Long.MAX_VALUE / 10) {
            break; // prevent overflow of factor
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number must be positive and a power of two must have only one bit set.
    if (n <= 0) {
        return false;
    }
    // The expression (n & (n - 1)) clears the least significant set bit.
    // If n is a power of two, the result will be zero.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non‑negative integer");
    }
    while (num >= 10) {
        int sum = 0;
        int temp = num;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    try {
        if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
            return 0;
        }
        int m = mat.length;
        int n = mat[0].length;
        int[][] horiz = new int[m][n];
        int[][] vert = new int[m][n];
        int[][] diag = new int[m][n];
        int[][] antiDiag = new int[m][n];
        int max = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i] == null || mat[i].length != n) {
                return 0;
            }
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                    vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    antiDiag[i][j] = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;
                    int cur = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                       Math.max(diag[i][j], antiDiag[i][j]));
                    if (cur > max) {
                        max = cur;
                    }
                }
            }
        }
        return max;
    } catch (Exception e) {
        return 0;
    }
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    // Use long to safely handle Integer.MIN_VALUE
    long absValue = negative ? -(long) n : n;
    StringBuilder sb = new StringBuilder(Long.toString(absValue));
    for (int i = sb.length() - 3; i > 0; i -= 3) {
        sb.insert(i, '.');
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int max = 0;
    for (int v : A) {
        if (v > max) max = v;
    }
    int limit = max * 2;
    boolean[] isSquare = new boolean[limit + 1];
    for (int i = 0; i * i <= limit; i++) {
        isSquare[i * i] = true;
    }
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    }
    int nUnique = freqMap.size();
    int[] vals = new int[nUnique];
    int[] counts = new int[nUnique];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
        vals[idx] = entry.getKey();
        counts[idx] = entry.getValue();
        idx++;
    }
    java.util.Arrays.sort(vals);
    class Rec {
        long dfs(int prev, int remaining) {
            if (remaining == 0) {
                return 1;
            }
            long total = 0;
            for (int i = 0; i < vals.length; i++) {
                if (counts[i] == 0) continue;
                if (prev == -1 || (prev + vals[i] <= limit && isSquare[prev + vals[i]])) {
                    counts[i]--;
                    total += dfs(vals[i], remaining - 1);
                    counts[i]++;
                }
            }
            return total;
        }
    }
    Rec r = new Rec();
    long result = r.dfs(-1, A.length);
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0;
    stack[top++] = -1; // sentinel
    long maxArea = 0L;
    for (int i = 0; i < n; i++) {
        while (top > 1 && heights[stack[top - 1]] >= heights[i]) {
            int height = heights[stack[--top]];
            int width = i - stack[top - 1] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }
    while (top > 1) {
        int height = heights[stack[--top]];
        int width = n - stack[top - 1] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return new int[0];
    }
    // Validate that all rows are non‑null and of equal length
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must be non‑null and of equal length");
        }
    }
    int[] result = new int[m * n];
    int pos = 0;
    try {
        for (int sum = 0; sum <= m + n - 2; sum++) {
            int startRow = Math.max(0, sum - (n - 1));
            int endRow = Math.min(m - 1, sum);
            if ((sum & 1) == 0) { // even diagonal -> reverse order
                for (int row = endRow; row >= startRow; row--) {
                    int col = sum - row;
                    result[pos++] = mat[row][col];
                }
            } else { // odd diagonal -> normal order
                for (int row = startRow; row <= endRow; row++) {
                    int col = sum - row;
                    result[pos++] = mat[row][col];
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issue, wrap and rethrow
        throw new RuntimeException("Error while computing diagonal order", e);
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find pivot: first index from end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // Already the highest permutation
        return -1;
    }

    // Find successor: first index from end that is greater than pivot
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap pivot and successor
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse suffix starting at i+1
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
    }

    if (result > Integer.MAX_VALUE || result <= n) {
        return -1;
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result.addAll(buildStrobogrammatic(n, n));
    return result;
}

private static List<String> buildStrobogrammatic(int current, int target) {
    if (current == 0) {
        List<String> base0 = new ArrayList<>();
        base0.add("");
        return base0;
    }
    if (current == 1) {
        List<String> base1 = new ArrayList<>();
        base1.add("0");
        base1.add("1");
        base1.add("8");
        return base1;
    }

    List<String> middle = buildStrobogrammatic(current - 2, target);
    List<String> res = new ArrayList<>();

    for (String mid : middle) {
        if (current == target) {
            res.add("1" + mid + "1");
            res.add("6" + mid + "9");
            res.add("8" + mid + "8");
            res.add("9" + mid + "6");
        } else {
            res.add("0" + mid + "0");
            res.add("1" + mid + "1");
            res.add("6" + mid + "9");
            res.add("8" + mid + "8");
            res.add("9" + mid + "6");
        }
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    try {
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
    } catch (Exception e) {
        // Any unexpected exception leads to false
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate twice the area of the triangle using cross product
    int areaTwice = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If areaTwice is zero, points are collinear => not a boomerang
    return areaTwice != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;

        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    // Handle null or empty input robustly
    if (s == null || s.isEmpty()) {
        return 0;
    }

    try {
        int maxLength = 1;
        int currentLength = 1;
        char prevChar = s.charAt(0);

        for (int i = 1; i < s.length(); i++) {
            char curChar = s.charAt(i);
            if (curChar == prevChar) {
                currentLength++;
            } else {
                if (currentLength > maxLength) {
                    maxLength = currentLength;
                }
                currentLength = 1; // reset for new character
                prevChar = curChar;
            }
        }

        // Final check in case the longest run is at the string's end
        if (currentLength > maxLength) {
            maxLength = currentLength;
        }

        return maxLength;
    } catch (Exception e) {
        // Return 0 in case of any unexpected runtime issue
        return 0;
    }
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>(n > 0 ? n : 0);
    if (n <= 0) {
        return result; // Return empty list for non-positive n
    }
    try {
        int current = 1;
        while (result.size() < n) {
            result.add(current);
            if (current <= n / 10) { // Can go deeper
                current *= 10;
            } else if (current % 10 != 9 && current + 1 <= n) { // Move to next sibling
                current++;
            } else { // Need to backtrack
                while (current % 10 == 9 && current / 10 > 0) {
                    current /= 10;
                }
                current++;
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return the achieved result so far
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : nums) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Trim leading/trailing spaces to avoid empty tokens at ends
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        // Preserve the original string's length of spaces if any
        return s;
    }
    String[] words = trimmed.split("\\s+");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        sb.append(new StringBuilder(words[i]).reverse());
        if (i != words.length - 1) {
            sb.append(' ');
        }
    }
    return sb.toString();
}
